sschase-maplemonk-wh.Maplemonk.misschase_unicommerce_fact_items WHERE LOWER(marketplace) LIKE \'%flipkart%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(fi.order_id as string) = cast(UFI.order_id as string) AND cast(fi.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from misschase-maplemonk-wh.Maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM misschase-maplemonk-wh.Maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(UFI.shipping_status, fi.ORDER_item_STATUS)) = LOWER(ShipMap.shipping_status) union all select cast(NULL AS string) customer_id, upper(mi.Shop_name) AS Shop_name, mi.marketplace, mi.CHANNEL, mi.SOURCE, mi.ORDER_ID, mi.ORDER_ID AS reference_code, NULL AS PHONE, null as NAME, COALESCE(ufi.EMAIL) AS EMAIL, CAST(ufi.shipping_last_update_date AS timestamp) AS SHIPPING_LAST_UPDATE_DATE, mi.SKU, cast(mi.sku_id as string) PRODUCT_ID, mi.PRODUCT_NAME, cast(null as string) as CURRENCY, UPPER(mi.CITY) AS CITY, UPPER(mi.STATE) AS State, UPPER(mi.order_status) AS Order_Status, CAST(mi.created_date AS DATE) AS Order_Date, CAST(mi.created_date AS datetime) Order_Time, mi.QUANTITY, (mi.selling_price - mi.tax_recovery) as GROSS_SALES_BEFORE_TAX, mi.DISCOUNT AS DISCOUNT, mi.tax_recovery as tax, mi.shipping_charge, mi.selling_price AS SELLING_PRICE, UPPER(ufi.order_status) AS OMS_order_status, UPPER(ufi.shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.minal_shipping_status, ufi.shipping_status)) AS miNAL_SHIPPING_STATUS, cast(order_line_id as string) AS SALEORDERITEMCODE, cast(order_line_id as string) AS SALES_ORDER_ITEM_ID, coalesce(mi.order_tracking_number,ufi.awb) AS AWB, NULL AS Payment_Gateway, UPPER(coalesce(ufi.payment_mode)) AS Payment_Mode, UPPER(coalesce(mi.courier_code,ufi.courier)) AS COURIER, coalesce(mi.shipped_date,ufi.dispatch_date) AS DISPATCH_DATE, coalesce(mi.delivered_date,ufi.delivered_date) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.minal_shipping_status, ufi.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, case when mi.return_quantity is not null then 1 else 0 end AS RETURN_FLAG, CASE WHEN mi.return_quantity is not null THEN CAST(mi.quantity AS INT64) END AS returned_quantity, CASE WHEN mi.return_quantity is not null THEN mi.selling_price END AS returned_sales, CASE WHEN mi.return_quantity is not null AND LOWER(mi.order_status) = \'cancelled\' THEN CAST(mi.quantity AS INT64) END AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.minal_shipping_status,ufi.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(mi.created_date AS DATE), DAY) WHEN LOWER(COALESCE(shipmap.minal_shipping_status, ufi.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(mi.created_date AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_D, COALESCE(mi.SKU, ufi.PRODUCT_ID) AS SKU_CODE, UPPER(mi.PRODUCT_NAME) AS PRODUCT_NAME_miNAL, UPPER(mi.mapped_CATEGORY) AS PRODUCT_CATEGORY, cast(mi.product_sub_category as string) AS PRODUCT_SUB_CATEGORY, mi.commonsku, UPPER(coalesce(cast(mi.warehouse_id as string),ufi.warehouse_name)) AS WAREHOUSE, COALESCE(mi.zipcode, ufi.pincode) AS pincode, fa.pincode source_pincode, cast(null as string) as discount_codes from maplemonk.Miss_Chase_Myntra_fact_items mi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM misschase-maplemonk-wh.Maplemonk.misschase_unicommerce_fact_items WHERE LOWER(marketplace) LIKE \'%myntra%\' ) ufi WHERE ufi.rw = 1 ) ufi ON cast(mi.order_id as string) = cast(ufi.order_id as string) AND cast(mi.sku_id as string) = cast(ufi.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from misschase-maplemonk-wh.Maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS minal_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM misschase-maplemonk-wh.Maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(ufi.shipping_status, mi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) ; CREATE OR REPLACE TABLE misschase-maplemonk-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL ; CREATE OR REPLACE TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM misschase-maplemonk-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM misschase-maplemonk-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN misschase-maplemonk-wh.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); CREATE TABLE IF NOT EXISTS misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_easyecom_returns_intermediate ( ORDER_ID INT64, INVOICE_ID INT64, SUBORDER_ID STRING, REFERENCE_CODE STRING, CREDIT_NOTE_ID INT64, ORDER_DATE TIMESTAMP, INVOICE_DATE TIMESTAMP, RETURN_DATE TIMESTAMP, MANIFEST_DATE TIMESTAMP, IMPORT_DATE TIMESTAMP, LAST_UPDATE_DATE TIMESTAMP, COMPANY_PRODUCT_ID STRING, PRODUCTNAME STRING, PRODUCT_ID STRING, SKU STRING, MARKETPLACE STRING, MARKETPLACE_ID INT64, REPLACEMENT_ORDER INT64, RETURN_REASON STRING, RETURNED_QUANTITY FLOAT64, RETURN_AMOUNT_WITHOUT_TAX FLOAT64, RETURN_TAX FLOAT64, RETURN_SHIPPING_CHARGE FLOAT64, RETURN_MISC FLOAT64, TOTAL_RETURN_AMOUNT FLOAT64 ); CREATE OR REPLACE TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE TABLE IF NOT EXISTS misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, FR.* FROM (select * from misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_unicommerce_returns_intermediate where RETURN_DISPLAYCODE is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE; CREATE OR REPLACE TABLE misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_returns_consolidated AS SELECT UPPER(er.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(RETURN_DATE as datetime) return_Date, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_easyecom_returns_fact_items er LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from misschase-maplemonk-wh.maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(er.marketplace) = lower(mm.marketplace) GROUP BY er.Marketplace, mm.final_marketplace, RETURN_DATE, Marketing_channel UNION ALL SELECT UPPER(fr.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(RETURN_COMPLETE_DATE as datetime) AS RETURN_DATE, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM misschase-maplemonk-wh.maplemonk.misschase_maplemonk_wh_unicommerce_returns_fact_items fr LEFT JOIN (select * from (Select *, row_number() over (partition by lower(marketplace) order by 1) rw from misschase-maplemonk-wh.maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fr.marketplace) = lower(mm.marketplace) GROUP BY fr.Marketplace, mm.FINAL_MARKETPLACE, RETURN_COMPLETE_DATE, Marketing_channel;",
                    "transaction": true
